function achFmtTimeHMS(ts) { const d = new Date(ts * 1000); const h = TimeManager.useLocal() ? d.getHours() : d.getUTCHours(); const m = TimeManager.useLocal() ? d.getMinutes() : d.getUTCMinutes(); const s = TimeManager.useLocal() ? d.getSeconds() : d.getUTCSeconds(); return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0') + ' ' + achTimeZoneSuffix(); }

function achBuildPageLocked() { return `<div class="bbgl-ach-locked"><div class="bbgl-ach-locked-icon">\u{1F512}</div><div class="bbgl-ach-locked-text">Reach Level 100 to unlock this page!</div></div>`; }

function achBuildPage0(d) { const ps = d.perStatBest || { bestTrain: {}, bestDay: {}, bestWeek: {}, bestMonth: {} }; const STATS = ['str', 'def', 'spd', 'dex']; const STAT_LABEL = { str: 'Strength', def: 'Defense', spd: 'Speed', dex: 'Dexterity' }; const rows = [{ key: 'best-train', short: 'Single Train', long: 'Highest Single Train', tip: 'Highest gains achieved from a single click, per individual stat.', recs: ps.bestTrain, getDate: r => achFmtDate(r.date), getTime: r => r.ts ? achFmtTimeHMS(r.ts) : '' }, { key: 'best-day', short: 'Best Day', long: 'Best Training Day', tip: 'Highest gains achieved in a single calendar day, per individual stat.', recs: ps.bestDay, getDate: r => achFmtDate(r.date) }, { key: 'best-week', short: 'Best Week', long: 'Best Training Week', tip: 'Highest gains achieved in a single calendar week, per individual stat.', recs: ps.bestWeek, getDate: r => achFmtWeekShort(r.weekOf) }, { key: 'best-month', short: 'Best Month', long: 'Best Month', tip: 'Highest gains achieved in a single calendar month, per individual stat.', recs: ps.bestMonth, getDate: r => achFmtMonthLong(r.rawMonth) }]; const headerStats = STATS.map(sk => `<div class="ach-stat-header ach-stat-${sk} bbgl-ach-col-copy" data-stat="${sk}" data-tooltip="Click to copy ${STAT_LABEL[sk]} column" style="cursor:pointer">${STAT_LABEL[sk]}</div>`).join(''); const header = `<div class="bbgl-ach-grid-header"><div class="ach-grid-label-area"><span class="bbgl-ach-section-title" data-ach-section="greatest-gains" data-clip-title="Greatest Gains" data-tooltip="Click any stat or row to copy its data, or click this title to copy the entire section to your clipboard.">Greatest Gains</span></div>${headerStats}</div>`; const rowsHTML = rows.map(r => { const labelArea = `<div class="ach-grid-label-area"><div class="ach-k"><span class="ach-title-short">${achEsc(r.short)}</span><span class="ach-title-long">${achEsc(r.long)}</span></div></div>`; const cells = STATS.map(sk => { const rec = r.recs ? r.recs[sk] : null; const valHTML = rec ? '+' + Formatter.dual(rec.value) : '<span class="ach-null">—</span>'; const dateHTML = rec ? `<div class="ach-date">${achEsc(r.getDate(rec))}</div>` : ''; const timeHTML = rec && r.getTime ? `<div class="ach-time">${achEsc(r.getTime(rec))}</div>` : ''; return `<div class="bbgl-ach-stat-cell" data-ach-key="${achEsc(r.key)}" data-stat="${sk}"><span class="ach-value">${valHTML}</span>${dateHTML}${timeHTML}</div>`; }).join(''); const tipAttr = r.tip ? ` data-tooltip="${achEsc(r.tip)}"` : ''; return `<div class="bbgl-ach-row bbgl-ach-row-multi" data-ach-key="${achEsc(r.key)}"${tipAttr}>${labelArea}${cells}</div>`; }).join(''); return `<div class="bbgl-ach-section bbgl-ach-section-page0">${header}${rowsHTML}</div>`; }

function achBuildPage1(d) { const STATS = ['str', 'def', 'spd', 'dex']; const STAT_LABEL = { str: 'Strength', def: 'Defense', spd: 'Speed', dex: 'Dexterity' }; const rows = [{ key: 'training-streak', short: 'Best Streak', long: 'Best Training Streak', tip: 'Total stats gained during your longest consecutive training streak.', len: d.longestStreak, start: d.longestStreakStart, end: d.longestStreakEnd, gains: d.longestStreakGains }, { key: 'green-streak', short: 'Best Green', long: 'Best Green Streak', tip: 'Total stats gained during your longest streak of achieving at least Green (1,000E+).', len: d.longestGoalStreak, start: d.longestGoalStreakStart, end: d.longestGoalStreakEnd, gains: d.longestGoalStreakGains }, { key: 'gold-streak', short: 'Best Gold', long: 'Best Gold Streak', tip: 'Total stats gained during your longest streak of achieving at least Gold (1,500E+).', len: d.longestGoldStreak, start: d.longestGoldStreakStart, end: d.longestGoldStreakEnd, gains: d.longestGoldStreakGains }, { key: 'diamond-streak', short: 'Best Diamond', long: 'Best Diamond Streak', tip: 'Total stats gained during your longest streak of achieving Diamond (2,000E+).', len: d.longestDiamondStreak, start: d.longestDiamondStreakStart, end: d.longestDiamondStreakEnd, gains: d.longestDiamondStreakGains }]; const headerStats = STATS.map(sk => `<div class="ach-stat-header ach-stat-${sk}">${STAT_LABEL[sk]}</div>`).join('') + `<div class="ach-stat-header ach-stat-tot">Total</div>`; const header = `<div class="bbgl-ach-grid-header"><div class="ach-grid-label-area"><span class="bbgl-ach-section-title" data-ach-section="sexiest-streaks" data-clip-title="Sexiest Streaks" data-tooltip="Click any stat or row to copy its data, or click this title to copy the entire section to your clipboard.">SEXIEST STREAKS</span></div>${headerStats}</div>`; const rowsHTML = rows.map(r => { const dayBit = `<span class="ach-streak-days">${r.len ? r.len + 'd' : '—'}</span>`; const presentStats = r.gains ? STATS.filter(sk => (r.gains[sk] || 0) > 0) : []; const total = presentStats.reduce((a, sk) => a + (r.gains[sk] || 0), 0); const dateText = r.start && r.end ? achEsc(achFmtStreakRange(r.start, r.end)) : '—'; const dateHTML = `<div class="ach-date ach-streak-date">${dayBit}<span class="ach-streak-sep">•</span><span class="ach-streak-daterange">${dateText}</span></div>`; const totalText = total > 0 ? '+' + achFmtGain(total) : '<span class="ach-null">—</span>'; const inlineDays = r.len ? `<span class="ach-streak-days ach-streak-days-inline"> · ${r.len}d</span>` : ''; const inlineDate = r.start && r.end ? `<span class="bbgl-ach-streak-date-inline">&nbsp;&nbsp;${dateText}</span>` : ''; const labelArea = `<div class="ach-grid-label-area"><div class="ach-k"><span class="ach-title-short">${achEsc(r.short)}</span><span class="ach-title-long">${achEsc(r.long)}</span>${inlineDays}${inlineDate}</div></div>`; const cells = STATS.map(sk => { const v = r.gains && r.gains[sk] || 0; const valHTML = v > 0 ? '+' + achEsc(achFmtGain(v)) : '<span class="ach-null">—</span>'; return `<div class="bbgl-ach-stat-cell" data-ach-key="${r.key}" data-stat="${sk}"><span class="ach-value">${valHTML}</span></div>`; }).join(''); const totalCell = `<div class="bbgl-ach-stat-cell bbgl-ach-stat-cell-total" data-ach-key="${r.key}" data-stat="total"><span class="ach-value ach-stat-tot">${totalText}</span></div>`; const tipAttr = r.tip ? ` data-tooltip="${achEsc(r.tip)}"` : ''; return `<div class="bbgl-ach-row bbgl-ach-row-multi" data-ach-key="${r.key}"${tipAttr}>${labelArea}${cells}${totalCell}${dateHTML}</div>`; }).join(''); const consVal = d.trainingRestRatio || '—'; const consDaysShort = ''; const consDaysLong = '(' + (d.trainingDays || 0) + '/' + (d.calDays || 0) + ' Days)'; const consRow = `<div class="bbgl-ach-row bbgl-ach-row-multi bbgl-ach-consistency-row" data-ach-key="consistency" data-tooltip="Your lifetime ratio of active training days versus total calendar days."><div class="bbgl-ach-consistency-text">Training Consistency: <span class="ach-cons-val">${achEsc(consVal)}</span> <span class="ach-cons-days">${achEsc(consDaysLong)}</span></div></div>`; return `<div class="bbgl-ach-section bbgl-ach-section-page0 bbgl-ach-section-page1">${header}${rowsHTML}${consRow}</div>`; }

function achFmtTimeHM(ts) { const d = new Date(ts * 1000); const h = TimeManager.useLocal() ? d.getHours() : d.getUTCHours(); const m = TimeManager.useLocal() ? d.getMinutes() : d.getUTCMinutes(); return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0'); }

function achBuildPage2(d) { const STAT_ABBR = { str: 'STR', def: 'DEF', spd: 'SPD', dex: 'DEX' }; const STAT_FULL = { str: 'Strength', def: 'Defense', spd: 'Speed', dex: 'Dexterity' }; const STATS = ['str', 'def', 'spd', 'dex']; const isExpanded = achIsExpandedMode(); const countRow = (label, shortLabel, count, key, tip, tipIsHtml) => { const clipVal = String(count); const tipAttr = tipIsHtml ? `data-tooltip-html="${tip}"` : `data-tooltip="${achEsc(tip)}"`; return `<div class="bbgl-ach-row" ${tipAttr} data-ach-key="${key}" data-clip="${achEsc(label + ': ' + clipVal)}"><div class="ach-row-main"><div class="ach-k-stack"><span class="ach-k"><span class="ach-title-long">${achEsc(label)}</span><span class="ach-title-short">${achEsc(shortLabel)}</span>:</span></div><div class="ach-v-wrap"><span class="ach-value">${achEsc(clipVal)}</span></div></div></div>`; }; const bestRow = (longLabel, shortLabel, rec, key, tip) => { if (!rec || !rec.stats) { return `<div class="bbgl-ach-hh-best-row" data-tooltip="${achEsc(tip)}" data-ach-key="${key}"><div class="bbgl-ach-hh-label"><span class="ach-k"><span class="ach-title-long">${achEsc(longLabel)}</span><span class="ach-title-short">${achEsc(shortLabel)}</span></span><div class="bbgl-ach-hh-date-line"><span class="ach-null">No jumps recorded yet</span></div></div><div class="bbgl-ach-hh-cells"><div class="bbgl-ach-hh-cell bbgl-ach-hh-cell-total"><span class="bbgl-ach-hh-tag ach-stat-tot">Total</span><span class="bbgl-ach-hh-val"><span class="ach-null">—</span></span></div></div></div>`; } const dateStr = achFmtDate(rec.date); const timeStr = achFmtTimeHM(rec.ts) + ' – ' + achFmtTimeHM(rec.tsEnd || rec.ts) + ' ' + achTimeZoneSuffix(); const timeStrClip = achFmtTimeHMClip(rec.ts) + ' – ' + achFmtTimeHMClip(rec.tsEnd || rec.ts) + ' TCT'; const trained = STATS.filter(sk => (rec.stats[sk] || 0) > 0); const statCells = trained.map(sk => `<div class="bbgl-ach-hh-cell bbgl-ach-hh-cell-stat bbgl-ach-stat-cell" data-ach-key="${key}" data-stat="${sk}" data-tooltip="Total ${achEsc(STAT_FULL[sk])} gained during this jump."><span class="bbgl-ach-hh-val">+${achEsc(achFmtGain(rec.stats[sk]))}</span><span class="bbgl-ach-hh-tag ach-stat-${sk}">${STAT_ABBR[sk]}</span></div>`).join(''); const totalCell = `<div class="bbgl-ach-hh-cell bbgl-ach-hh-cell-total bbgl-ach-stat-cell" data-ach-key="${key}" data-stat="total" data-tooltip="Total overall stats gained during this jump."><span class="bbgl-ach-hh-tag ach-stat-tot">Total</span><span class="bbgl-ach-hh-val">+${achEsc(achFmtGain(rec.value))}</span></div>`; const clipParts = trained.map(sk => STAT_ABBR[sk] + ': +' + achFmtGain(rec.stats[sk])); clipParts.push('Total: +' + achFmtGain(rec.value)); return `<div class="bbgl-ach-hh-best-row" data-tooltip="${achEsc(tip)}" data-ach-key="${key}" data-clip="${achEsc(longLabel + ' (' + dateStr + ', ' + timeStrClip + '): ' + clipParts.join(' | '))}" data-clip-date="${achEsc(dateStr + '  ' + timeStrClip)}"><div class="bbgl-ach-hh-label"><span class="ach-k"><span class="ach-title-long">${achEsc(longLabel)}</span><span class="ach-title-short">${achEsc(shortLabel)}</span></span><div class="bbgl-ach-hh-date-line">${achEsc(dateStr)}<span class="bbgl-ach-hh-time"> &nbsp; ${achEsc(timeStr)}</span></div></div><div class="bbgl-ach-hh-cells">${statCells}${totalCell}</div></div>`; }; const hjCount = countRow('Happy Jumps Performed', 'Happy Jumps', d.happyJumps || 0, 'hj-count', 'Total number of Happy Jumps performed.<br><i>HJ = 1000E+ spent within 15m of using Ecstasy</i>', true); const hjBest = bestRow('Best Happy Jump', 'Best Jump', d.bestHappyJump && d.bestHappyJump.total, 'best-hj', 'The single Happy Jump that yielded the highest combined stat gain.'); const rowsHTML = `<div class="bbgl-ach-hh-group" data-ach-key="happy-jumps-group">${hjCount}${hjBest}</div>`; let clipAll = `Happy Jumps Performed: ${d.happyJumps || 0}\nBest Happy Jump: ${d.bestHappyJump && d.bestHappyJump.total ? (() => { const rec = d.bestHappyJump.total; const trained = STATS.filter(sk => (rec.stats[sk] || 0) > 0); const parts = trained.map(sk => STAT_ABBR[sk] + ': +' + achFmtGain(rec.stats[sk])); parts.push('Total: +' + achFmtGain(rec.value)); return parts.join(' | '); })() : '—'}`; let helpersHTML = ''; if (d.happyItemTotals) { const hhOrder = { 2180: 1, 2210: 2, 2020: 3, 8983: 4 }; const helpers = HAPPY_LOGS.map(id => { const rec = d.happyItemTotals[id] || { count: 0, happy: 0 }; const meta = ITEM_LOG_META[id]; return { id, label: meta.achLabel || meta.label, short: meta.short || meta.label, count: rec.count, happy: rec.happy }; }).filter(h => h.count > 0).sort((a,
    b) => (hhOrder[a.id] || 99) - (hhOrder[b.id] || 99)); if (helpers.length > 0) { const helperRow = h => { const tip = isExpanded ? `Amount of ${h.label} · Happy Gained` : `Amount of ${h.label}`; const clipVal = `${h.label}: ${h.count} (${Formatter.number(h.happy)} Happy)`; let html = `<div class="bbgl-ach-row" data-tooltip="${achEsc(tip)}" data-ach-key="happy-helper-${h.id}" data-clip="${achEsc(clipVal)}"><div class="ach-row-main"><div class="ach-k-stack"><span class="ach-k"><span class="ach-title-long">${achEsc(h.label)}</span><span class="ach-title-short">${achEsc(h.short)}</span>:</span></div><div class="ach-v-wrap"><span class="ach-value">${Formatter.number(h.count)}</span><span class="ach-value ach-happy-col">+${achEsc(achFmtGain(h.happy))} <span class="ach-happy-word">H</span></span></div></div></div>`; if (h.id === 2210 && d.odItemTotals && d.odItemTotals[EX_OD_LOG] && d.odItemTotals[EX_OD_LOG].count > 0) { const exRec = d.odItemTotals[EX_OD_LOG]; const countHtml = achEsc(Formatter.number(exRec.count)); const lostNum = exRec.happyLost > 0 ? `-${achEsc(Formatter.number(exRec.happyLost))}` : '<span class="ach-null">—</span>'; const eLostNum = exRec.energyLost > 0 ? `-${achEsc(Formatter.number(exRec.energyLost))}` : '<span class="ach-null">—</span>'; const gainedHtml = `<div style="display:flex; flex-direction:column; align-items:flex-end; gap:4px; line-height:1.2;">
                    <div>${lostNum} <span class="ach-happy-word ach-od-happy-word">H</span></div>
                    <div>${eLostNum} <span class="ach-enh-e-label" style="color:#c06060;">E</span></div>
                </div>`; const exOdLabel = achOdLabel(ITEM_LOG_META[EX_OD_LOG].label); const exTip = isExpanded ? `Amount of ${exOdLabel} · Happy / Energy Lost` : `Amount of ${exOdLabel}`; const exClip = `${ITEM_LOG_META[EX_OD_LOG].label}: ${exRec.count} (-${Formatter.number(exRec.happyLost)} H, -${Formatter.number(exRec.energyLost)} E)`; html += `<div class="bbgl-ach-row bbgl-ach-od-row bbgl-subgroup-row bbgl-subgroup-row-last" data-tooltip="${achEsc(exTip)}" data-ach-key="happy-od-${EX_OD_LOG}" data-clip="${achEsc(exClip)}"><div class="ach-row-main" style="align-items:flex-start;"><div class="ach-k-stack"><span class="ach-k"><span class="ach-title-long">ODs:</span><span class="ach-title-short">ODs:</span></span></div><div class="ach-v-wrap" style="align-items:flex-start;"><span class="ach-value" style="padding-top:1px;">${countHtml}</span><span class="ach-value ach-happy-col ach-enh-od">${gainedHtml}</span></div></div></div>`; } return html; }; const colCount = 2; const rpc = Math.ceil(helpers.length / colCount); const cols = []; for (let i = 0; i < colCount; i++) { const start = i * rpc; const chunk = helpers.slice(start, start + rpc); if (chunk.length) { cols.push(`<div class="bbgl-ach-col">${chunk.map(helperRow).join('')}</div>`); } } const clipHelpers = helpers.map(h => `${h.label}: ${h.count} (${Formatter.number(h.happy)} Happy)`).join('\n'); clipAll += '\n\n— Happy Helpers —\n' + clipHelpers; helpersHTML = `<div class="bbgl-ach-cols" style="grid-template-columns:repeat(${colCount},minmax(0,1fr)); padding-top:1px; padding-bottom:0;">${cols.join('')}</div>`; } } return `<div class="bbgl-ach-section bbgl-ach-section-hh"><div class="bbgl-ach-title-row"><span class="bbgl-ach-section-title" data-ach-section="happy-hopping" data-clip-section="${achEsc(clipAll)}" data-clip-title="Happy Hopping" data-tooltip="Click any stat or row to copy its data, or click this title to copy the entire section to your clipboard.">HAPPY HOPPING</span></div>${rowsHTML}${helpersHTML}</div>`; }

function computeEnhancersForPeriod(sl) { const energyItemTotals = {}; ENERGY_LOGS.forEach(id => { energyItemTotals[id] = { count: 0, energy: 0 }; }); const odItemTotals = {}; OD_LOGS.forEach(id => { odItemTotals[id] = { count: 0, energyLost: 0, happyLost: 0 }; }); const statEnhByStat = { str: { count: 0, gain: 0 }, def: { count: 0, gain: 0 }, spd: { count: 0, gain: 0 }, dex: { count: 0, gain: 0 } }; const days = sl._dailyList && sl._dailyList.length > 0 ? sl._dailyList : sl.date ? [app.DataController.getDateMap()[sl.date]] : []; days.forEach(day => { if (!day) return; if (day.items) { ENERGY_LOGS.forEach(id => { const qty = day.items[id] || 0; if (qty > 0) energyItemTotals[id].count += qty; }); OD_LOGS.forEach(id => { const qty = day.items[id] || 0; if (qty > 0) odItemTotals[id].count += qty; }); } (day.series || []).forEach(e => { if (e.type === 'item' && e.energy && energyItemTotals[e.logId]) energyItemTotals[e.logId].energy += e.energy; if (e.type === 'item' && e.energyLost != null && odItemTotals[e.logId]) odItemTotals[e.logId].energyLost += e.energyLost; if (e.type === 'item' && e.happyLost != null && odItemTotals[e.logId]) odItemTotals[e.logId].happyLost += e.happyLost; if (e.type === 'item' && e.statKey && statEnhByStat[e.statKey]) { statEnhByStat[e.statKey].count++; statEnhByStat[e.statKey].gain = Math.round((statEnhByStat[e.statKey].gain + (e.statGain || 0)) * 100) / 100; } }); }); return { energyItemTotals, odItemTotals, statEnhByStat }; }

function achBuildPageOverview(d) { const NULL = '<span class="ach-null">—</span>'; const enh = d.statEnhByStat || {}; const enrg = d.energyItemTotals || {}; const od = d.odItemTotals || {}; const STAT_ABBR = { str: 'Str', def: 'Def', spd: 'Spd', dex: 'Dex' }; const isExpanded = achIsExpandedMode(); const STAT_ENH_MAP = { 2150: 'str', 2130: 'spd', 2140: 'def', 2120: 'dex' }; const LEFT_COL = [2150, 2130, 2290, 2040, 4900]; const RIGHT_COL = [2140, 2120, 2230, 2190, 8981]; const OD_AFTER = { 2290: XANAX_OD_LOG, 2230: LSD_OD_LOG }; const buildRow = id => { const meta = ITEM_LOG_META[id]; const label = meta.achLabel || meta.label; const tipLabel = meta.achTipLabel || label; const sk = STAT_ENH_MAP[id]; let countHtml, gainedHtml, clipVal, tip; if (sk) { const rec = enh[sk] || { count: 0, gain: 0 }; countHtml = rec.count > 0 ? achEsc(Formatter.number(rec.count)) : NULL; const gainNum = rec.gain > 0 ? `+${achEsc(Formatter.achAbbr(rec.gain, ACH_FMT.enhancers))}` : NULL; gainedHtml = `${gainNum} <span class="ach-stat-${sk}">${STAT_ABBR[sk]}</span>`; clipVal = `${label}: ${rec.count} (+${Formatter.achAbbr(rec.gain, ACH_FMT.enhancers)} ${STAT_ABBR[sk]})`; tip = isExpanded ? `Amount of ${tipLabel} · ${achStatFull(sk)} Gained` : `Amount of ${tipLabel}`; } else { const rec = enrg[id] || { count: 0, energy: 0 }; countHtml = rec.count > 0 ? achEsc(Formatter.number(rec.count)) : NULL; const gainNum = rec.energy > 0 ? `+${achEsc(Formatter.achAbbr(rec.energy, ACH_FMT.enhancers))}` : NULL; gainedHtml = `${gainNum} <span class="ach-enh-e-label">E</span>`; clipVal = `${label}: ${rec.count} (+${Formatter.achAbbr(rec.energy, ACH_FMT.enhancers)} Energy)`; tip = isExpanded ? `Amount of ${tipLabel} · Energy Gained` : `Amount of ${tipLabel}`; } const key = `enh-${id}`; return `<div class="bbgl-ach-row bbgl-ach-enh-row" data-tooltip="${achEsc(tip)}" data-ach-key="${key}" data-clip="${achEsc(clipVal)}"><div class="ach-row-main"><div class="ach-k-stack"><span class="ach-k"><span class="ach-title-long">${achEsc(label)}:</span><span class="ach-title-short">${achEsc(label)}:</span></span></div><div class="ach-v-wrap"><span class="ach-value">${countHtml}</span><span class="ach-value ach-enh-gained">${gainedHtml}</span></div></div></div>`; }; const buildODSubRow = odId => { const meta = ITEM_LOG_META[odId]; const rec = od[odId] || { count: 0, energyLost: 0 }; const countHtml = rec.count > 0 ? achEsc(Formatter.number(rec.count)) : NULL; const lostNum = rec.energyLost > 0 ? `-${achEsc(Formatter.number(rec.energyLost))}` : NULL; const gainedHtml = `${lostNum} <span class="ach-enh-e-label">E</span>`; const odLabel = achOdLabel(meta.label); const tip = isExpanded ? `Amount of ${odLabel} · Energy Lost` : `Amount of ${odLabel}`; const clipVal = `${meta.label}: ${rec.count} (-${Formatter.number(rec.energyLost)} Energy Lost)`; const key = `enh-${odId}`; return `<div class="bbgl-ach-row bbgl-ach-enh-row bbgl-ach-od-row bbgl-subgroup-row bbgl-subgroup-row-last" data-tooltip="${achEsc(tip)}" data-ach-key="${key}" data-clip="${achEsc(clipVal)}"><div class="ach-row-main"><div class="ach-k-stack"><span class="ach-k"><span class="ach-title-long">ODs:</span><span class="ach-title-short">ODs:</span></span></div><div class="ach-v-wrap"><span class="ach-value">${countHtml}</span><span class="ach-value ach-enh-gained ach-enh-od">${gainedHtml}</span></div></div></div>`; }; const buildColHTML = col => col.map(id => { let html = buildRow(id); const odId = OD_AFTER[id]; if (odId && od[odId] && od[odId].count > 0) html += buildODSubRow(odId); return html; }).join(''); const leftHTML = buildColHTML(LEFT_COL); const rightHTML = buildColHTML(RIGHT_COL); const clipAll = [...LEFT_COL, ...RIGHT_COL].map(id => { const meta = ITEM_LOG_META[id]; const label = meta.achLabel || meta.label; const sk = STAT_ENH_MAP[id]; if (sk) { const rec = enh[sk] || { count: 0, gain: 0 }; return `${label}: ${rec.count} (+${Formatter.achAbbr(rec.gain, ACH_FMT.enhancers)} ${STAT_ABBR[sk]})`; } const rec = enrg[id] || { count: 0, energy: 0 }; return `${label}: ${rec.count} (+${Formatter.achAbbr(rec.energy, ACH_FMT.enhancers)} Energy)`; }).join('\n'); const cols = `<div class="bbgl-ach-col">${leftHTML}</div><div class="bbgl-ach-col">${rightHTML}</div>`; const isPeriod = !!viewState.achEnhPeriodMode; const switchHTML = `<div class="bbgl-enh-mode-switch" data-tooltip-html="<b>Changes the data scope displayed on this page.</b><br><i><b>All-Time</b> shows totals across your entire log history. <b>Selected</b> shows data for the selected period on the calendar.</i>" data-tooltip-side="left"><span class="bbgl-enh-sw-opt${isPeriod ? '' : ' active'}" data-mode="alltime">All-Time</span><span class="bbgl-enh-sw-opt${isPeriod ? ' active' : ''}" data-mode="selected">Selected</span></div>`; return `<div class="bbgl-ach-section bbgl-ach-section-energy"><div class="bbgl-ach-title-row"><span class="bbgl-ach-section-title" data-ach-section="endocrine-enhancers" data-clip-section="${achEsc(clipAll)}" data-clip-title="Endocrine Enhancers" data-tooltip="Click any row to copy its data, or click this title to copy the entire section to your clipboard.">ENDOCRINE ENHANCERS</span>${switchHTML}</div><div class="bbgl-ach-cols" style="grid-template-columns:repeat(2,minmax(0,1fr));">${cols}</div></div>`; }

